    public static let stageOrder: [String] = ["see", "try", "undo", "recall"]
    public static let recoverySequence: [String] = ["mistake", "undo", "repair"]

    private static let states: [FirstChordFlowState] = [
        FirstChordFlowState(id: "see", stage: .see, wordIndex: 0, recovery: .makeMistake, target: "sat", completion: "start", nextID: "try-0"),
        FirstChordFlowState(id: "try-0", stage: .tryIt, wordIndex: 0, recovery: .makeMistake, target: "sat", completion: "physicalWord", nextID: "try-1"),
        FirstChordFlowState(id: "try-1", stage: .tryIt, wordIndex: 1, recovery: .makeMistake, target: "hat", completion: "physicalWord", nextID: "try-2"),
        FirstChordFlowState(id: "try-2", stage: .tryIt, wordIndex: 2, recovery: .makeMistake, target: "tan", completion: "physicalWord", nextID: "undo-mistake"),
        FirstChordFlowState(id: "undo-mistake", stage: .recover, wordIndex: 0, recovery: .makeMistake, target: "hat", completion: "physicalWord", nextID: "undo-command"),
        FirstChordFlowState(id: "undo-command", stage: .recover, wordIndex: 0, recovery: .undoMistake, target: nil, completion: "physicalUndo", nextID: "undo-repair"),
        FirstChordFlowState(id: "undo-repair", stage: .recover, wordIndex: 0, recovery: .repair, target: "sat", completion: "physicalWord", nextID: "recall-0"),
        FirstChordFlowState(id: "recall-0", stage: .recall, wordIndex: 0, recovery: .makeMistake, target: "tan", completion: "physicalWord", nextID: "recall-1"),
        FirstChordFlowState(id: "recall-1", stage: .recall, wordIndex: 1, recovery: .makeMistake, target: "sat", completion: "physicalWord", nextID: "recall-2"),
