        let state = firstChordState(stage: stage, wordIndex: wordIndex, recovery: recovery)
        let target = state.target == nil ? nil : (word ?? state.target)
        let wordForTitle = target ?? ""
        let demo = firstChordDemonstration(step: demonstrationIndex)
        switch state.id {
        case "see":
            return FirstChordPresentation(stageID: "see", label: "See",
                title: "Your first chord", instruction: demo.instruction, target: target,
                primaryAction: demo.primaryAction, primaryActionID: (demo.output == nil ? "demonstrate" : "start"), placeholder: "",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: false, nextStageID: "try")
        case "try-0":
            return FirstChordPresentation(stageID: "try", label: "Try",
                title: "Type “" + wordForTitle + "”", instruction: "Hold the highlighted keys together, then release all of them.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "undo")
        case "try-1":
