                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "undo")
        case "try-2":
            return FirstChordPresentation(stageID: "try", label: "Try",
                title: "Type “" + wordForTitle + "”", instruction: "Hold the highlighted keys together, then release all of them.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "undo")
        case "undo-mistake":
            return FirstChordPresentation(stageID: "undo", label: "Undo",
                title: "Type “" + wordForTitle + "”", instruction: "Type the wrong word. You’ll undo it next.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "recall")
        case "undo-command":
            return FirstChordPresentation(stageID: "undo", label: "Undo",
                title: "Undo “hat”", instruction: "Use the Undo chord to remove the whole word.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "recall")
        case "undo-repair":
            return FirstChordPresentation(stageID: "undo", label: "Undo",
                title: "Type “" + wordForTitle + "”", instruction: "Hold the highlighted keys together, then release all of them.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: true || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "recall")
        case "recall-0":
            return FirstChordPresentation(stageID: "recall", label: "Recall",
                title: "Type “" + wordForTitle + "”", instruction: "Type the word without the guide.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: false || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "finished")
        case "recall-1":
            return FirstChordPresentation(stageID: "recall", label: "Recall",
                title: "Type “" + wordForTitle + "”", instruction: "Type the word without the guide.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: false || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "finished")
        case "recall-2":
            return FirstChordPresentation(stageID: "recall", label: "Recall",
                title: "Type “" + wordForTitle + "”", instruction: "Type the word without the guide.", target: target,
                primaryAction: "Start typing", primaryActionID: "capture", placeholder: "Start typing to begin.",
                hintsVisible: false || hintRevealed,
                physicalReleaseRequired: true, nextStageID: "finished")
        case "finished":
            return FirstChordPresentation(stageID: "finished", label: "Finished",
                title: "Introduction complete", instruction: "Continue with the lessons.", target: target,
                primaryAction: "Open lessons", primaryActionID: "lessons", placeholder: "",
                hintsVisible: false || hintRevealed,
                physicalReleaseRequired: false, nextStageID: nil)
