    public static func lesson(stage: LearningStage) -> LessonPresentation {
        switch stage {
        case .see:
            return LessonPresentation(title: "Guide", instruction: "Hold the highlighted keys together, then release all of them.", primaryAction: "Start typing")
        case .tryIt:
            return LessonPresentation(title: "Guided practice", instruction: "Type the passage with the guide.", primaryAction: "Start typing")
        case .recall:
            return LessonPresentation(title: "Type from memory", instruction: "Type the passage from memory. Show a hint if you need one.", primaryAction: "Start typing")
        case .use:
            return LessonPresentation(title: "Use it in your writing", instruction: "Write a note or code fragment with the chords you practiced.", primaryAction: "Open editor")
        }
    }
